// neon.test.js — physics, brick bounce, score rules and transitions.
//
// Pure logic only (no DOM, zero dependencies), per CONTRIBUTING.md.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  resolveBricks,
  tick,
  ballSpeed,
  comboMultiplier,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

