// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Brick bounce: the reported symptom (the ball plows through bricks) -----

test('brick: falling on the top face flips vy and pushes the ball out', () => {
  const s = createState(1);
  const brick = s.bricks[0];
  s.ball = { x: brick.x + brick.w / 2, y: brick.y - 8, r: 7, vx: 0, vy: ballSpeed(1) };
  step(s, 1 / 60);
  assert.equal(brick.alive, false);
  assert.ok(s.ball.vy < 0, 'vy must flip upward');
  assert.equal(s.ball.y, brick.y - 7, 'ball pushed out above the brick');
  assert.equal(s.combo, 1);
});

test('brick: ball is outside the rectangle after the bounce', () => {
  const s = createState(1);
  const brick = s.bricks[0];
  s.ball = { x: brick.x + brick.w / 2, y: brick.y - 8, r: 7, vx: 0, vy: ballSpeed(1) };
  step(s, 1 / 60);
  assert.equal(collides(s.ball, brick), false);
});

test('brick: side hit flips vx and pushes the ball out sideways', () => {
  const s = createState(1);
  const brick = s.bricks[0];
  // 1px into the left face, vertically centred: the least penetration is X.
  s.ball = { x: brick.x - 6, y: brick.y + brick.h / 2, r: 7, vx: ballSpeed(1), vy: 0 };
  resolveBricks(s);
  assert.equal(brick.alive, false);
  assert.ok(s.ball.vx < 0, 'vx must flip leftward');
  assert.equal(s.ball.x, brick.x - 7, 'ball pushed out to the left');
});

test('brick: corner hit (equal penetration) flips both axes', () => {
  const s = createState(1);
  const brick = s.bricks[0];
  // Straddling the top-left corner: 6px into the top face, 6px into the left.
  s.ball = { x: brick.x - 1, y: 47, r: 7, vx: -ballSpeed(1), vy: ballSpeed(1) };
  resolveBricks(s);
  assert.equal(brick.alive, false);
  assert.ok(s.ball.vx > 0 && s.ball.vy < 0, 'both components flip at a corner');
});

test('brick: one flip per axis at a seam (no double inversion)', () => {
  const s = createState(1);
  const top = s.bricks[0];
  const bottom = s.bricks[BRICK_COLS];
  // Straddling the seam: inside the bottom of `top` AND the top of `bottom`.
  s.ball = { x: top.x + top.w / 2, y: 72, r: 7, vx: 0, vy: ballSpeed(1) };
  resolveBricks(s);
  assert.equal(top.alive, false);
  assert.equal(bottom.alive, false);
  assert.equal(s.ball.vy, -ballSpeed(1), 'exactly one inversion: the ball bounces back up');
  assert.equal(s.ball.y, bottom.y - 7, 'ball exits through the top of the lower brick');
});

// --- Tunneling and frame-rate independence ---------------------------------

test('brick: no tunneling at the dt cap on level 6', () => {
  const s = createState(6);
  const brick = s.bricks[0];
  s.ball = { x: brick.x + brick.w / 2, y: brick.y - 8, r: 7, vx: 0, vy: ballSpeed(6) };
  step(s, 0.05);
  assert.equal(brick.alive, false);
  assert.ok(s.ball.vy < 0, 'ball must bounce off the top face, not cross it');
  assert.ok(s.ball.y < brick.y, 'ball must end above the brick');
});

test('physics: same bounce outcome at 30 fps, 144 fps and the 50ms cap', () => {
  const outcome = (dt) => {
    const s = createState(6);
    const brick = s.bricks[0];
    s.ball = { x: brick.x + brick.w / 2, y: brick.y - 8, r: 7, vx: 0, vy: ballSpeed(6) };
    let guard = 0;
    while (s.ball.vy > 0 && guard++ < 2000) step(s, dt);
    return { vx: s.ball.vx, vy: s.ball.vy, dead: !brick.alive };
  };
  const a = outcome(1 / 30);
  const b = outcome(1 / 144);
  const c = outcome(0.05);
  assert.deepEqual(a, b);
  assert.deepEqual(a, c);
  assert.ok(a.vy < 0 && a.dead, 'the bounce happens at every frame rate');
});

// --- Paddle ----------------------------------------------------------------

test('paddle: no tunneling at high speed (dt cap, level 6)', () => {
  const s = createState(6);
  s.ball = { x: s.paddle.x + s.paddle.w / 2, y: s.paddle.y - 8, r: 7, vx: 0, vy: ballSpeed(6) };
  step(s, 0.05);
  assert.ok(s.ball.vy < 0, 'ball must bounce off the paddle top');
  assert.ok(s.ball.y + s.ball.r <= s.paddle.y, 'ball must end above the paddle');
});

test('paddle: dead-center hit keeps a playable angle', () => {
  const s = createState(1);
  s.ball = { x: s.paddle.x + s.paddle.w / 2, y: s.paddle.y - 8, r: 7, vx: 0, vy: ballSpeed(1) };
  step(s, 1 / 60);
  assert.ok(Math.abs(s.ball.vx) > 30, 'vx must not collapse to ~0');
  assert.ok(s.ball.vy < 0);
});

test('paddle: rebound conserves the level speed', () => {
  const s = createState(3);
  // Edge hit: the strongest angle change, where the old code grew the norm.
  s.ball = { x: s.paddle.x, y: s.paddle.y - 8, r: 7, vx: 0, vy: ballSpeed(3) };
  step(s, 1 / 60);
  const norm = Math.hypot(s.ball.vx, s.ball.vy);
  assert.ok(Math.abs(norm - ballSpeed(3)) < 1e-6, `norm ${norm} must equal ${ballSpeed(3)}`);
  assert.ok(s.ball.vy < 0);
});

// --- Score / combo ---------------------------------------------------------

test('comboMultiplier: bounded', () => {
  assert.equal(comboMultiplier(0), 1);
  assert.ok(comboMultiplier(100) <= 8, 'multiplier must be bounded');
  assert.equal(comboMultiplier(50), comboMultiplier(100), 'multiplier plateaus at the cap');
});

test('brick: counted once, scored once', () => {
  const s = createState(1);
  const brick = s.bricks[0];
  s.ball = { x: brick.x + brick.w / 2, y: brick.y - 8, r: 7, vx: 0, vy: ballSpeed(1) };
  step(s, 1 / 60);
  const score = s.score;
  const combo = s.combo;
  resolveBricks(s); // a second pass must be a no-op
  assert.equal(s.score, score);
  assert.equal(s.combo, combo);
});

// --- Transitions -----------------------------------------------------------

test('transition: combo resets and the level advances when the last brick falls', () => {
  const s = createState(1);
  s.combo = 9;
  const brick = s.bricks[0];
  for (const b of s.bricks) b.alive = false;
  brick.alive = true;
  s.ball = { x: brick.x + brick.w / 2, y: brick.y - 8, r: 7, vx: 0, vy: ballSpeed(1) };
  const outcome = tick(s, 1 / 60);
  assert.equal(outcome.cleared, true);
  assert.equal(s.level, 2);
  assert.equal(s.combo, 0);
  assert.ok(s.ball.vy < 0, 'ball is relaunched upward');
});

test('transition: game over on the last life', () => {
  const s = createState(1);
  s.lives = 1;
  s.ball = { x: WIDTH / 2, y: belowField(), r: 7, vx: 0, vy: 400 };
  const outcome = tick(s, 1 / 60);
  assert.equal(outcome.gameOver, true);
  assert.equal(s.lives, 0);
});

