edits.newText:
// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// Brick collision is resolved by the pure `resolveBricks()` during `step()`;
// `frame()` only renders. The module runs nothing on import: only `boot()`
// touches the DOM. Pure logic can therefore be imported from the tests
// (`node --test`) without a browser.

export const BRICK_TOP = 48;

// Minimum |hit| for a paddle rebound: a dead-center touch must not collapse
// vx to ~0 (a purely vertical trajectory is unplayable).
export const PADDLE_MIN_HIT = 0.25;

const STORAGE_KEY = 'neon.best';

