edits.newText:
export function createState(level = 1) {
  const speed = ballSpeed(level);
  // The launch direction (up-right) is normalized to the level's speed, so
  // that every later rebound — which only flips components — keeps the norm.
  const launch = { vx: speed * 0.5, vy: -speed };
  const launchNorm = Math.hypot(launch.vx, launch.vy);
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: {
      x: WIDTH / 2,
      y: PADDLE_Y - BALL_R - 2,
      r: BALL_R,
      vx: (launch.vx * speed) / launchNorm,
      vy: (launch.vy * speed) / launchNorm,
    },
    bricks: makeBricks(level),
  };
}

