edits.oldText:
// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

edits.newText:
// --- Brick bounce (pure) ---------------------------------------------------

// Resolves the ball against every live brick it overlaps in one pass. Each
// touched brick is killed and scored; then AT MOST ONE rebound per axis is
// applied — two seam bricks touched in the same pass must not cancel their
// two flips (the ball would cross the seam) — and the ball is pushed back out
// of the brick it bounced on, so it never starts the next pass overlapping a
// live brick.
// The axis is the one of least penetration; equal penetration means a corner
// hit and BOTH components flip. Returns true if at least one brick was hit.
export function resolveBricks(state) {
  const { ball } = state;
  const hit = [];
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    hit.push(brick);
  }
  if (hit.length === 0) return false;

  const first = hit[0];
  const overlapX = Math.min(
    ball.x + ball.r - first.x,
    first.x + first.w - (ball.x - ball.r),
  );
  const overlapY = Math.min(
    ball.y + ball.r - first.y,
    first.y + first.h - (ball.y - ball.r),
  );
  const bounceY = overlapY <= overlapX;
  const bounceX = overlapX <= overlapY;

  if (bounceY) {
    if (ball.vy > 0) {
      // Falling: the ball is entering a TOP face — the one it is closest to.
      let target = first;
      for (const b of hit) {
        if (ball.y + ball.r - b.y < ball.y + ball.r - target.y) target = b;
      }
      ball.y = target.y - ball.r;
    } else {
      // Rising: the ball is entering a BOTTOM face.
      let target = first;
      for (const b of hit) {
        if (b.y + b.h - (ball.y - ball.r) < target.y + target.h - (ball.y - ball.r)) {
          target = b;
        }
      }
      ball.y = target.y + target.h + ball.r;
    }
    ball.vy = -ball.vy;
  }
  if (bounceX) {
    if (ball.vx > 0) {
      // Moving right: entering a LEFT face.
      let target = first;
      for (const b of hit) {
        if (ball.x + ball.r - b.x < ball.x + ball.r - target.x) target = b;
      }
      ball.x = target.x - ball.r;
    } else {
      // Moving left: entering a RIGHT face.
      let target = first;
      for (const b of hit) {
        if (b.x + b.w - (ball.x - ball.r) < target.x + target.w - (ball.x - ball.r)) {
          target = b;
        }
      }
      ball.x = target.x + target.w + ball.r;
    }
    ball.vx = -ball.vx;
  }
  return true;
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Movement is sub-stepped so that no obstacle band can be crossed between two
// samples: the per-sub-step travel stays well below the thinnest band the
// ball can pass (a brick row: BRICK_H + 2*BALL_R = 34px; the paddle:
// PADDLE_H + 2*BALL_R = 26px). This removes both tunneling — ballSpeed(6) *
// 0.05s = 35.5px > 34px at the dt cap — and the frame-rate dependence of the
// bounce outcome: the bounce is detected at the first sub-step that overlaps,
// and the push-out places the ball deterministically on the face.
const SUBSTEP = 8; // maximum per-sub-step travel, in pixels, per axis

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks (brick resolution is the pure
// `resolveBricks()`, so it is testable without a DOM).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const speed = ballSpeed(state.level);
  const maxMove = Math.max(Math.abs(ball.vx), Math.abs(ball.vy)) * dt;
  const steps = Math.max(1, Math.ceil(maxMove / SUBSTEP));
  const h = dt / steps;

  for (let i = 0; i < steps; i++) {
    // Side walls
    ball.x += ball.vx * h;
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    ball.y += ball.vy * h;
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      // The rebound angle depends on where the paddle was hit; a dead-center
      // hit is clamped so vx can never collapse to ~0 (unplayable angle).
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      const sign = hit < 0 ? -1 : 1;
      const clamped = sign * Math.max(Math.abs(hit), PADDLE_MIN_HIT);
      ball.vx = speed * 0.6 * clamped;
      // The ball always leaves the paddle at the level's speed.
      ball.vy = -Math.sqrt(speed * speed - ball.vx * ball.vx);
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks
    resolveBricks(state);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Game tick (pure) ------------------------------------------------------

// Runs one animation step and applies its consequences: level cleared (all
// bricks dead), ball lost (life lost, relaunch or game over). The combo is
// reset on every relaunch — life lost OR level cleared, the ball is
// re-thrown. Cleared wins over lost: the ball that breaks the last brick is
// done, its trailing flight cannot cost the player a life.
export function tick(state, dt) {
  const lost = step(state, dt);

  if (state.bricks.every((b) => !b.alive)) {
    state.level += 1;
    state.combo = 0;
    state.bricks = makeBricks(state.level);
    state.ball = createState(state.level).ball;
    return { lost, cleared: true, gameOver: false };
  }

  if (lost) {
    state.lives -= 1;
    state.combo = 0;
    if (state.lives <= 0) {
      return { lost, cleared: false, gameOver: true };
    }
    state.ball = createState(state.level).ball;
  }

  return { lost, cleared: false, gameOver: false };
}

